// Extracted by gdp-wired/extract from p17.py (Meter, a class and its methods).
// Checked against the code it was read from; read again with extract() after the code changes.
import {all, any, bool, forall, intern, nat, record, rule, yes} from 'gdp-wired'

export const meterRule = rule("Meter")
  .state({n: 0})
  .maps({cache_: record({has: bool, value: nat}).from({has: false, value: 0})})
  .step(({cache_}) => ({n: 1, cache_: cache_.set(intern('k'), {has: yes, value: 1})}))

// What every state of the code is: a law about every state is about the code's with these beside it.
export const meterInvariants = [meterRule.law("cache_: a key it doesn't hold holds the defaults", ({cache_}) => forall(k => any(cache_.at(k).has, all(cache_.at(k).value.eq(0)))))]
